def fill_enclosed(grid, fill=None):
    """Cells of the background color not reachable from the border without crossing non-background colors become `fill`."""
    from collections import deque
    h,w=len(grid),len(grid[0])
    bg=grid[0][0]
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and grid[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    if fill is None:
        fill=max(v for r in grid for v in r)+1
    return [[fill if grid[i][j]==bg and not seen[i][j] else grid[i][j] for j in range(w)] for i in range(h)]

